/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    computeResearchLabLevel, coerceLabsLabLevel, findCanonicalLabResearchSlug, normalizeLabsLabLevelMap
 * depends    src/data/labs/categories, src/data/labs/overview, src/data/labs/research, src/support/own-lookup
 * used by    src/calculators/specs.generated, src/data/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { ownLookup } from '../../support/own-lookup'
import { findLabResearchByDisplayName, findLabResearchBySlug } from './research'
import { CANONICAL_LAB_SLUG_BY_ALIAS } from './categories'
import { isLabsResearchLabName } from './overview'

function clampInt(value: number, min: number, max: number): number {
  return Math.floor(Math.min(max, Math.max(min, value)))
}

function normalizeLookupKey(value: string): string {
  return value.trim().toLowerCase().replace(/[_\s]+/g, ' ')
}

/**
 * Resolve a research lab level from display-name keyed levels.
 * Matches slug, canonical slug, catalog displayName, and fuzzy display-name equality.
 */
export function computeResearchLabLevel(
  researchLabLevels: Record<string, number>,
  slug: string,
  maxLevel = 99,
): number {
  const canonical = ownLookup(CANONICAL_LAB_SLUG_BY_ALIAS, slug) ?? slug
  const research = findLabResearchBySlug(canonical) ?? findLabResearchBySlug(slug)
  const candidateKeys = [
    slug,
    canonical,
    research?.displayName,
    research?.slug,
  ].filter((key): key is string => typeof key === 'string' && key.length > 0)

  for (const key of candidateKeys) {
    // `researchLabLevels` is the caller's own record — saved settings, a save file —
    // so it gets the same treatment as our catalogs.
    const value = ownLookup(researchLabLevels, key)
    if (typeof value === 'number' && Number.isFinite(value)) {
      return clampInt(value, 0, maxLevel)
    }
  }

  if (research?.displayName) {
    const target = normalizeLookupKey(research.displayName)
    for (const [key, value] of Object.entries(researchLabLevels)) {
      if (!Number.isFinite(value)) continue
      if (normalizeLookupKey(key) === target) {
        return clampInt(value, 0, maxLevel)
      }
    }
  }

  return 0
}

/** A lab level as a non-negative integer — from a number, a numeric string, or a `{ current }`-shaped record. */
export function coerceLabsLabLevel(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }
  if (typeof value === 'string' && value.trim().length > 0) {
    const parsed = Number(value)
    if (Number.isFinite(parsed)) return Math.max(0, Math.floor(parsed))
  }
  if (value && typeof value === 'object') {
    const source = value as Record<string, unknown>
    for (const key of ['current', 'currentLevel', 'level'] as const) {
      const candidate = source[key]
      if (typeof candidate === 'number' && Number.isFinite(candidate)) {
        return Math.max(0, Math.floor(candidate))
      }
    }
  }
  return undefined
}

/** Resolve a lab key — slug, display name, or the malformed name some saves carry — to a catalog slug. */
export function findCanonicalLabResearchSlug(key: string | null | undefined): string | null {
  const trimmed = String(key || '').trim()
  if (!trimmed) return null

  const bySlug = findLabResearchBySlug(trimmed)
  if (bySlug?.slug) return bySlug.slug

  const byDisplay = findLabResearchByDisplayName(trimmed)
  if (byDisplay?.slug) return byDisplay.slug

  return isLabsResearchLabName(trimmed) ? trimmed : null
}

/** A lab level map keyed by catalog slugs only, with non-negative integer values; the higher level wins on a collision. */
export function normalizeLabsLabLevelMap(
  input: Record<string, unknown> | null | undefined,
): Record<string, number> {
  if (!input || typeof input !== 'object') return {}
  const out: Record<string, number> = {}
  for (const [key, raw] of Object.entries(input)) {
    if (!key.trim()) continue
    const slug = findCanonicalLabResearchSlug(key)
    if (!slug) continue
    const level = coerceLabsLabLevel(raw)
    if (level === undefined) continue
    out[slug] = Math.max(out[slug] ?? 0, level)
  }
  return out
}
